/* Published content comes from the server API. Guest game/order state remains separate. */
(() => {
  let catalog=[],notices=[],policies={};
  const escape=authEscape;
  const originalShop=shop,originalTerms=termsPage,originalPrivacy=privacyPage,originalLinks=policyLinks;
  const imageURL=item=>item.images?.[0]?.url||'';
  const safeImage=value=>typeof value==='string'&&/^\/api\/public\/images\/[A-Za-z0-9_-]+$/.test(value)?value:'';
  shop=function(){if(!catalog.length)return originalShop();return `${ad()}<div class="intro"><div><p class="eyebrow">POINT SHOP</p><h1>포인트몰</h1><p class="sub">WEAR QUEST의 상품을 만나보세요.</p></div></div><div class="products">${catalog.map((p,i)=>`<article class="product"><button class="product-art" data-server-product="${i}"><img loading="lazy" src="${escape(safeImage(imageURL(p)))}" alt="${escape(p.name)}"></button><div class="body"><span class="eyebrow">${p.isTest?'SAMPLE PRODUCT':'WEAR QUEST'}</span><h3>${escape(p.name)}</h3><p class="sub">${escape(p.description.slice(0,70))}</p><div class="between"><b>${Number(p.points)} P</b></div><button class="primary" data-server-product="${i}">상품 보기 ↗</button></div></article>`).join('')}</div><p class="footnote">운영 상품 주문 연결 준비 중 · 기기 내 체험 포인트로 실제 주문할 수 없습니다.</p>`;};
  function policy(kind){const p=policies[kind];if(!p)return '';return `<article class="policy-page"><button class="text-button" onclick="go('home')">← 홈으로</button><span class="eyebrow">WEAR QUEST POLICY</span><h1>${escape(p.title)}</h1><p class="sub">버전 ${escape(p.version)} · 시행일 ${escape(p.effectiveDate)}</p><div style="white-space:pre-wrap;line-height:1.9">${escape(p.body)}</div></article>`;}
  termsPage=()=>policy('terms')||originalTerms();privacyPage=()=>policy('privacy')||originalPrivacy();
  policyLinks=()=>originalLinks()+`<footer class="policy-links"><button data-public-notices>공지사항</button>${['points','cart'].filter(k=>policies[k]).map(k=>`<button data-public-policy="${k}">${k==='points'?'포인트 지침':'장바구니 지침'}</button>`).join('')}</footer>`;
  document.addEventListener('click',e=>{const el=e.target.closest('[data-server-product],[data-public-notices],[data-public-policy]');if(!el)return;if(el.dataset.serverProduct!==undefined){const p=catalog[+el.dataset.serverProduct];if(!p)return;openModal(`<span class="eyebrow">${p.isTest?'SAMPLE PRODUCT':'WEAR QUEST'}</span><h2>${escape(p.name)}</h2><img style="width:100%;max-height:380px;object-fit:cover" src="${escape(safeImage(imageURL(p)))}" alt="${escape(p.name)}"><p style="white-space:pre-wrap">${escape(p.description)}</p><h3>${Number(p.points)} P</h3><p class="sub">${p.options.map(o=>`${escape(o.color)} / ${escape(o.size)} ${o.stock>0?'':'(품절)'}`).join(' · ')}</p><p class="checkout-note">실제 상품 주문 연결 준비 중입니다. 현재는 상품 정보를 확인할 수 있어요.</p>`);}else if(el.dataset.publicPolicy)openModal(policy(el.dataset.publicPolicy));else openModal(`<h2>공지사항</h2>${notices.length?notices.map(n=>`<article><h3>${n.pinned?'[공지] ':''}${escape(n.title)}</h3><p style="white-space:pre-wrap">${escape(n.body)}</p></article>`).join(''):'<p class="sub">게시된 공지사항이 없습니다.</p>'}`);});
  async function get(path){const r=await fetch('/api/public/'+path);if(!r.ok)throw Error('public content unavailable');return r.json();}
  Promise.allSettled([get('products').then(d=>catalog=d.items||[]),get('notices').then(d=>notices=(d.items||[]).sort((a,b)=>Number(b.pinned)-Number(a.pinned))),...['terms','privacy','points','cart'].map(k=>get('policies/'+k).then(d=>policies[k]=d.item))]).then(()=>{if(['shop','terms','privacy','home'].includes(route))render();});
})();
